// Generated by Cypress Author on 2026-11-22.
describe('Swag Labs page performance', () => {
  it('loads the home page in under 2500ms with TTFB under 800ms', () => {
    cy.visit('/', {
      onBeforeLoad(window) {
        window.performance.mark('saucedemo-navigation-start');
      },
    });

    cy.window().then((window) => {
      const { performance } = window;
      const navigation = performance.getEntriesByType('navigation')[0];

      performance.mark('saucedemo-page-loaded');
      performance.measure(
        'saucedemo-page-load-duration',
        'saucedemo-navigation-start',
        'saucedemo-page-loaded',
      );

      const pageLoadDuration = performance.getEntriesByName(
        'saucedemo-page-load-duration',
      )[0].duration;
      const timeToFirstByte = navigation.responseStart - navigation.startTime;

      expect(pageLoadDuration, 'page load duration').to.be.lessThan(2500);
      expect(timeToFirstByte, 'time to first byte').to.be.lessThan(800);
    });
  });
});
